CREATE TABLE IF NOT EXISTS system_agent_context_packs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,team_id UUID,task_id UUID,context_key TEXT NOT NULL,content JSONB NOT NULL DEFAULT '{}'::jsonb,version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS system_agent_decisions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,team_id UUID,task_id UUID,agent_id UUID,decision TEXT NOT NULL,confidence NUMERIC(6,2),reasoning_ref JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS system_agent_conflicts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,team_id UUID,task_id UUID,conflict_type TEXT NOT NULL,participants JSONB NOT NULL DEFAULT '[]'::jsonb,status TEXT NOT NULL DEFAULT 'open',resolution JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS system_agent_team_health (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,team_id UUID,health_score NUMERIC(6,2),status TEXT NOT NULL,signals JSONB NOT NULL DEFAULT '{}'::jsonb,recorded_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_agent_context_user ON system_agent_context_packs(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_agent_decision_user ON system_agent_decisions(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_agent_conflict_user ON system_agent_conflicts(user_id,status);
CREATE INDEX IF NOT EXISTS idx_agent_team_health_user ON system_agent_team_health(user_id,recorded_at DESC);